text:
  "tStartMs": 1372604,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "對 在那邊"
  } ]
}, {
  "tStartMs": 1373605,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "然後那個看板"
  } ]
}, {
  "tStartMs": 1375507,
  "dDurationMs": 2803,
  "segs": [ {
    "utf8": "就是那個日本70年代的那種景象"
  } ]
}, {
  "tStartMs": 1378310,
  "dDurationMs": 2035,
  "segs": [ {
    "utf8": "OK 這個真的講下去 "
  } ]
}, {
  "tStartMs": 1380345,
  "dDurationMs": 1068,
  "segs": [ {
    "utf8": "回憶講不完"
  } ]
}, {
  "tStartMs": 1381413,
  "dDurationMs": 3203,
  "segs": [ {
    "utf8": "但是拉回來講到說場所的這個部分"
  } ]
}, {
  "tStartMs": 1384616,
  "dDurationMs": 2586,
  "segs": [ {
    "utf8": "其實我們知道說像東京也有秋葉原"
  } ]
}, {
  "tStartMs": 1387202,
  "dDurationMs": 1185,
  "segs": [ {
    "utf8": "也有中野"
  } ]
}, {
  "tStartMs": 1388387,
  "dDurationMs": 3119,
  "segs": [ {
    "utf8": "養活了一大批40歲以上"
  } ]
}, {
  "tStartMs": 1391506,
  "dDurationMs": 2620,
  "segs": [ {
    "utf8": "然後回頭要買自己的童年的人"
  } ]
}, {
  "tStartMs": 1394126,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "那你會不會覺得說"
  } ]
}, {
  "tStartMs": 1396128,
  "dDurationMs": 1551,
  "segs": [ {
    "utf8": "那到底是一種生意 "
  } ]
}, {
  "tStartMs": 1397679,
  "dDurationMs": 2035,
  "segs": [ {
    "utf8": "還算是一種基礎設施"
  } ]
}, {
  "tStartMs": 1399714,
  "dDurationMs": 1302,
  "segs": [ {
    "utf8": "我一直都覺得就是"
  } ]
}, {
  "tStartMs": 1401016,
  "dDurationMs": 2119,
  "segs": [ {
    "utf8": "因為像我剛剛講的中華商場"
  } ]
}, {
  "tStartMs": 1403135,
  "dDurationMs": 3270,
  "segs": [ {
    "utf8": "它賣的東西可能就比中野來得更大"
  } ]
}, {
  "tStartMs": 1406405,
  "dDurationMs": 1568,
  "segs": [ {
    "utf8": "我覺得中野可能更像萬年吧"
  } ]
}, {
  "tStartMs": 1407973,
  "dDurationMs": 1601,
  "segs": [ {
    "utf8": "比較像大萬年"
  } ]
}, {
  "tStartMs": 1409574,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "我覺得更像萬年"
  } ]
}, {
  "tStartMs": 1410475,
  "dDurationMs": 2403,
  "segs": [ {
    "utf8": "我們必須說還好萬年現在還在"
  } ]
}, {
  "tStartMs": 1412878,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "對 真的"
  } ]
}, {
  "tStartMs": 1414379,
  "dDurationMs": 1135,
  "segs": [ {
    "utf8": "而且像我去日本 "
  } ]
}, {
  "tStartMs": 1415514,
  "dDurationMs": 1468,
  "segs": [ {
    "utf8": "我就很愛去中野"
  } ]
}, {
  "tStartMs": 1416982,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "我中野通常可以逛兩天"
  } ]
}, {
  "tStartMs": 1418784,
  "dDurationMs": 700,
  "segs": [ {
    "utf8": "OK"
  } ]
}, {
  "tStartMs": 1419484,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "因為逛不完"
  } ]
}, {
  "tStartMs": 1420485,
  "dDurationMs": 1485,
  "segs": [ {
    "utf8": "你逛的比我多"
  } ]
}, {
  "tStartMs": 1421970,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "對 我都是逛兩天"
  } ]
}, {
  "tStartMs": 1423371,
  "dDurationMs": 2103,
  "segs": [ {
    "utf8": "所以就是那邊一直挖寶一直挖寶"
  } ]
}, {
  "tStartMs": 1425474,
  "dDurationMs": 2502,
  "segs": [ {
    "utf8": "然後一些可能展覽的海報"
  } ]
}, {
  "tStartMs": 1427976,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "它可能就你那時候它是非賣品"
  } ]
}, {
  "tStartMs": 1429778,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "但是可能就會流入到市面"
  } ]
}, {
  "tStartMs": 1431580,
  "dDurationMs": 2402,
  "segs": [ {
    "utf8": "然後就會有人用二手的價格在販賣"
  } ]
}, {
  "tStartMs": 1433982,
  "dDurationMs": 2703,
  "segs": [ {
    "utf8": "因為中野對我來說是一個人生很重要的"
  } ]
}, {
  "tStartMs": 1436685,
  "dDurationMs": 1384,
  "segs": [ {
    "utf8": "其實對於我來講就是 "
  } ]
}, {
  "tStartMs": 1438069,
  "dDurationMs": 1819,
  "segs": [ {
    "utf8": "雖然我是台北人"
  } ]
}, {
  "tStartMs": 1439888,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "但是我人生重要的記憶"
  } ]
}, {
  "tStartMs": 1441289,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "我都會去那邊挖寶"
  } ]
}, {
  "tStartMs": 1442390,
  "dDurationMs": 651,
  "segs": [ {
    "utf8": "明白"
  } ]
}, {
  "tStartMs": 1443041,
  "dDurationMs": 1051,
  "segs": [ {
    "utf8": "像我覺得"
  } ]
}, {
  "tStartMs": 1444092,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "因為萬年也都還在"
  } ]
}, {
  "tStartMs": 1445694,
  "dDurationMs": 3303,
  "segs": [ {
    "utf8": "但是我們其實並沒有刻意的去保留"
  } ]
}, {
  "tStartMs": 1448997,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "那我就覺得是有點可惜"
  } ]
}, {
  "tStartMs": 1450799,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "因為在我小時候"
  } ]
}, {
  "tStartMs": 1452100,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "我不可能一天到晚去日本"
  } ]
}, {
  "tStartMs": 1453702,
  "dDurationMs": 1585,
  "segs": [ {
    "utf8": "那時候我們去的就是萬年"
  } ]
}, {
  "tStartMs": 1455287,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "去的就是西門町"
  } ]
}, {
  "tStartMs": 1456688,
  "dDurationMs": 2402,
  "segs": [ {
    "utf8": "我們都趴在那個玻璃櫥窗前面"
  } ]
}, {
  "tStartMs": 1459090,
  "dDurationMs": 1102,
  "segs": [ {
    "utf8": "那時候就是看著這個"
  } ]
}, {
  "tStartMs": 1460192,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "對 就是看著這個"
  } ]
}, {
  "tStartMs": 1461693,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "然後就買不起"
  } ]
}, {
  "tStartMs": 1462794,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "我覺得這些變化不是不行"
  } ]
}, {
  "tStartMs": 1464596,
  "dDurationMs": 868,
  "segs": [ {
    "utf8": "然後要都更"
  } ]
}, {
  "tStartMs": 1465464,
  "dDurationMs": 1334,
  "segs": [ {
    "utf8": "要做什麼都不是不行"
  } ]
}, {
  "tStartMs": 1466798,
  "dDurationMs": 1552,
  "segs": [ {
    "utf8": "因為它本來就是"
  } ]
}, {
  "tStartMs": 1468350,
  "dDurationMs": 1701,
  "segs": [ {
    "utf8": "城市往前進的一個方式"
  } ]
